// ---- Mars Life Line style header (generated by scripts/kiln-style-sync.mjs from src/style/tokens.json, style v2) ----
// Paste at the top of every .kiln.js source. Do not edit colours here; edit tokens.json and re-run npm run style:sync.
const PALETTE = {
  'space-deep': 0x20283D,
  'shadow-plum': 0x765768,
  'regolith-mid': 0xB95C40,
  'regolith-light': 0xE6A26A,
  'structure-white': 0xF2E5D2,
  'structure-gray': 0x686976,
  'trim-dark': 0x303240,
  'accent-orange': 0xFF8A24,
  'accent-cyan': 0x54E5F5,
  'accent-blue': 0x35CFFF,
  'glass-tint': 0xEBD9C5,
  'cell-blue': 0x2F58B8,
  'grow-magenta': 0xE040FB,
  'plant-green': 0x5A9E58,
  'ice-pale': 0xD8EEF8
};

const BUDGETS = {"small-prop":1500,"medium-prop":6000,"vehicle":9000,"building":12000,"character":8000,"rock":400};
const SEGMENTS = {"small":8,"default":12,"large":16};

// Bevel radius for roundedBoxGeo: ratio of the smallest dimension (style range 0.06-0.12).
function bevel(w, h, d, ratio = 0.09) {
  return Math.min(w, h, d) * ratio;
}

// One shared material per role. Variants (e.g. structure-gray) take an explicit colour token.
function styleMaterials() {
  const m = {"matte-environment":{"description":"Terrain, rocks, craters, mountains. Fully matte, no reflections.","colors":["regolith-mid","regolith-light","shadow-plum"],"roughness":0.95,"metalness":0},"smooth-structure":{"description":"Buildings, modules, vehicles, suits, crates. Clean satin finish, never mirror-like.","colors":["structure-white","structure-gray"],"roughness":0.55,"metalness":0.05},"accent-paint":{"description":"Non-glowing orange colour blocking: side panels, crate faces, dome base band, suit pads, wheel hubs.","colors":["accent-orange"],"roughness":0.6,"metalness":0},"dark-trim":{"description":"Tyres, recesses, joints, vents.","colors":["trim-dark"],"roughness":0.85,"metalness":0},"emissive-warm":{"description":"Door frames, window strips, headlights. Selected surfaces only.","colors":["accent-orange"],"emissive":"accent-orange","emissiveIntensity":1.6,"roughness":0.5,"metalness":0},"emissive-cool":{"description":"Beacons, indicators, screens. Smaller and rarer than warm lights.","colors":["accent-cyan","accent-blue"],"emissive":"accent-cyan","emissiveIntensity":1.4,"roughness":0.5,"metalness":0},"glass":{"description":"Greenhouse domes, module windows. Light tint, soft highlight, see-through.","colors":["glass-tint"],"roughness":0.15,"metalness":0,"opacity":0.35},"visor":{"description":"Helmet visors and vehicle windshields. Opaque near-black, glossy, shows a soft highlight.","colors":["space-deep"],"roughness":0.12,"metalness":0.1},"solar-cell":{"description":"Solar panel cell faces. Deep blue, semi-gloss, framed by structure-white grid bars.","colors":["cell-blue"],"roughness":0.35,"metalness":0.1}};
  const make = (role, colorToken) => {
    const spec = m[role];
    const color = PALETTE[colorToken ?? spec.colors[0]];
    const name = colorToken && colorToken !== spec.colors[0] ? role + ':' + colorToken : role;
    if (role === 'glass') return glassMaterial(color, { opacity: spec.opacity, roughness: spec.roughness, metalness: spec.metalness, name });
    const opts = { roughness: spec.roughness, metalness: spec.metalness, name };
    if (spec.emissive) Object.assign(opts, { emissive: PALETTE[spec.emissive], emissiveIntensity: spec.emissiveIntensity });
    return gameMaterial(color, opts);
  };
  return {
    rock: make('matte-environment'),
    rockLight: make('matte-environment', 'regolith-light'),
    rockShadow: make('matte-environment', 'shadow-plum'),
    panel: make('smooth-structure'),
    panelGray: make('smooth-structure', 'structure-gray'),
    accent: make('accent-paint'),
    trim: make('dark-trim'),
    glowWarm: make('emissive-warm'),
    glowCool: make('emissive-cool'),
    glowBlue: make('emissive-cool', 'accent-blue'),
    glass: make('glass'),
    visor: make('visor'),
    solarCell: make('solar-cell'),
  };
}
// ---- end style header ----

const meta = {
  name: 'lab-bench',
  role: 'prop',
  reference: 'models and assets images/phase-5/lab-bench.png'
};

function build() {
  const root = createRoot('lab-bench');
  const m = styleMaterials();

  // Desk geometry dimensions:
  // Desk length along Z: 2.0 m (from Z = -1.0 to +1.0)
  // Desk depth along X: 0.84 m (from X = -0.42 to +0.42, +X is front)
  // Desk height to countertop Y: 0.82 m

  // -------------------------------------------------------------------------
  // 1. PLINTH FEET & BASE FRAMES (Y = 0 to 0.12)
  // -------------------------------------------------------------------------
  const basePivot = createPivot('Plinths', [0, 0, 0], root);

  // Left pedestal plinth foot (+Z side, center Z = 0.66)
  const footW = 0.84;
  const footL = 0.64;
  const footH = 0.12;

  // Left flared plinth base
  createPart('PlinthLeftBottom', boxGeo(footW + 0.06, 0.05, footL + 0.06), m.panelGray, {
    position: [0, 0.025, 0.66],
    parent: basePivot
  });
  createPart('PlinthLeftMain', boxGeo(footW, 0.07, footL), m.panelGray, {
    position: [0, 0.085, 0.66],
    parent: basePivot
  });

  // Right pedestal plinth foot (-Z side, center Z = -0.66)
  createPart('PlinthRightBottom', boxGeo(footW + 0.06, 0.05, footL + 0.06), m.panelGray, {
    position: [0, 0.025, -0.66],
    parent: basePivot
  });
  createPart('PlinthRightMain', boxGeo(footW, 0.07, footL), m.panelGray, {
    position: [0, 0.085, -0.66],
    parent: basePivot
  });

  // Corner foot chamfer pads (front and back corners of plinths)
  for (const signX of [1, -1]) {
    for (const signZ of [1, -1]) {
      const pX = signX * (footW * 0.5 + 0.02);
      // Left plinth corners
      createPart(`CornerFootPad_L_${signX}_${signZ}`, boxGeo(0.08, 0.10, 0.08), m.panelGray, {
        position: [pX, 0.05, 0.66 + signZ * (footL * 0.5 + 0.02)],
        parent: basePivot
      });
      // Right plinth corners
      createPart(`CornerFootPad_R_${signX}_${signZ}`, boxGeo(0.08, 0.10, 0.08), m.panelGray, {
        position: [pX, 0.05, -0.66 + signZ * (footL * 0.5 + 0.02)],
        parent: basePivot
      });
    }
  }

  // -------------------------------------------------------------------------
  // 2. PEDESTAL BODIES & OUTER CHASSIS (Y = 0.12 to 0.72)
  // -------------------------------------------------------------------------
  const chassisPivot = createPivot('Chassis', [0, 0, 0], root);
  const pedH = 0.60;
  const pedY = 0.12 + pedH / 2; // Y = 0.42

  // Outer slate wrap-around framing
  // Left outer rib frame
  createPart('OuterFrame_L', boxGeo(footW, pedH, 0.08), m.panelGray, {
    position: [0, pedY, 0.98],
    parent: chassisPivot
  });
  // Right outer rib frame
  createPart('OuterFrame_R', boxGeo(footW, pedH, 0.08), m.panelGray, {
    position: [0, pedY, -0.98],
    parent: chassisPivot
  });

  // Left inner kneehole wall
  createPart('InnerKneeWall_L', boxGeo(footW - 0.04, pedH, 0.07), m.panelGray, {
    position: [0, pedY, 0.34],
    parent: chassisPivot
  });
  // Right inner kneehole wall
  createPart('InnerKneeWall_R', boxGeo(footW - 0.04, pedH, 0.07), m.panelGray, {
    position: [0, pedY, -0.34],
    parent: chassisPivot
  });

  // Left outer end panel (+Z side: prominent orange chamfered panel on ivory)
  createPart('EndPanelIvory_L', boxGeo(footW - 0.06, pedH - 0.06, 0.03), m.panel, {
    position: [0, pedY, 1.025],
    parent: chassisPivot
  });
  createPart('EndPanelOrange_L', boxGeo(footW - 0.18, pedH - 0.16, 0.04), m.accent, {
    position: [0, pedY, 1.035],
    parent: chassisPivot
  });

  // Right outer end panel (-Z side: prominent orange chamfered panel on ivory)
  createPart('EndPanelIvory_R', boxGeo(footW - 0.06, pedH - 0.06, 0.03), m.panel, {
    position: [0, pedY, -1.025],
    parent: chassisPivot
  });
  createPart('EndPanelOrange_R', boxGeo(footW - 0.18, pedH - 0.16, 0.04), m.accent, {
    position: [0, pedY, -1.035],
    parent: chassisPivot
  });

  // Rear back panel spanning the entire desk
  createPart('BackModestyPanel', boxGeo(0.06, pedH - 0.04, 1.94), m.trim, {
    position: [-footW / 2 + 0.03, pedY, 0],
    parent: chassisPivot
  });

  // Kneehole archway top chamfer brackets (aligned in YZ plane, facing front/back)
  createPart('KneeBracket_L', boxGeo(footW - 0.08, 0.10, 0.10), m.panelGray, {
    position: [0, 0.12 + pedH - 0.05, 0.30],
    rotation: [45, 0, 0],
    parent: chassisPivot
  });
  createPart('KneeBracket_R', boxGeo(footW - 0.08, 0.10, 0.10), m.panelGray, {
    position: [0, 0.12 + pedH - 0.05, -0.30],
    rotation: [-45, 0, 0],
    parent: chassisPivot
  });

  // Front pedestal face surrounds (ivory frame with slate outer margin)
  createPart('DrawerSurround_L', boxGeo(0.05, pedH - 0.04, footL - 0.06), m.panel, {
    position: [footW / 2 - 0.01, pedY, 0.66],
    parent: chassisPivot
  });
  createPart('DrawerSurround_R', boxGeo(0.05, pedH - 0.04, footL - 0.06), m.panel, {
    position: [footW / 2 - 0.01, pedY, -0.66],
    parent: chassisPivot
  });

  // -------------------------------------------------------------------------
  // 3. DRAWERS (2 on Left Pedestal, 2 on Right Pedestal)
  // -------------------------------------------------------------------------
  const drawerPivot = createPivot('Drawers', [0, 0, 0], root);

  function createDrawer(name, pos) {
    const dW = 0.06;
    const dH = 0.21;
    const dL = 0.46;

    // Ivory backing frame around drawer
    createPart(`${name}_Bezel`, boxGeo(dW - 0.01, dH + 0.03, dL + 0.04), m.panel, {
      position: [pos[0] - 0.01, pos[1], pos[2]],
      parent: drawerPivot
    });

    // Main vibrant orange drawer face
    createPart(`${name}_Face`, boxGeo(dW, dH, dL), m.accent, {
      position: pos,
      parent: drawerPivot
    });

    // Chamfer corner pads on drawer face
    for (const signY of [1, -1]) {
      for (const signZ of [1, -1]) {
        createPart(`${name}_Chamfer_${signY}_${signZ}`, boxGeo(dW + 0.005, 0.04, 0.04), m.accent, {
          position: [pos[0], pos[1] + signY * (dH * 0.5 - 0.018), pos[2] + signZ * (dL * 0.5 - 0.018)],
          rotation: [signY * signZ * 45, 0, 0],
          parent: drawerPivot
        });
      }
    }

    // Recessed dark pull handle cutout along top edge
    createPart(`${name}_HandleRecess`, boxGeo(dW + 0.015, 0.035, dL * 0.46), m.trim, {
      position: [pos[0] + 0.006, pos[1] + dH * 0.5 - 0.02, pos[2]],
      parent: drawerPivot
    });
  }

  // Left drawers (Z = 0.66, Upper & Lower)
  createDrawer('Drawer_L_Upper', [footW / 2 + 0.025, 0.56, 0.66]);
  createDrawer('Drawer_L_Lower', [footW / 2 + 0.025, 0.28, 0.66]);

  // Right drawers (Z = -0.66, Upper & Lower)
  createDrawer('Drawer_R_Upper', [footW / 2 + 0.025, 0.56, -0.66]);
  createDrawer('Drawer_R_Lower', [footW / 2 + 0.025, 0.28, -0.66]);

  // -------------------------------------------------------------------------
  // 4. COUNTERTOP / WORKTOP SLAB (Y = 0.72 to 0.82)
  // -------------------------------------------------------------------------
  const topPivot = createPivot('Countertop', [0, 0, 0], root);
  const topW = 0.88;
  const topL = 2.04;
  const topH = 0.10;
  const topY = 0.72 + topH / 2; // 0.77

  // Main ivory worktop slab
  createPart('WorktopSlab', boxGeo(topW, topH, topL), m.panel, {
    position: [0, topY, 0],
    parent: topPivot
  });

  // Slate side caps/shoulders wrapping the ends of the worktop
  createPart('WorktopEnd_L', boxGeo(topW + 0.02, topH + 0.02, 0.06), m.panelGray, {
    position: [0, topY, topL / 2 + 0.01],
    parent: topPivot
  });
  createPart('WorktopEnd_R', boxGeo(topW + 0.02, topH + 0.02, 0.06), m.panelGray, {
    position: [0, topY, -topL / 2 - 0.01],
    parent: topPivot
  });

  // -------------------------------------------------------------------------
  // 5. WORKTOP INSERTS & EQUIPMENT
  // -------------------------------------------------------------------------

  // A. Left insert: Sample holder tray with 3 circular wells (+Z side)
  const sampleHolderPivot = createPivot('sample_holder', [0, 0.82, 0.62], root);

  // Recessed tray rim
  createPart('SampleTrayRim', boxGeo(0.52, 0.03, 0.62), m.panel, {
    position: [0, 0.015, 0],
    parent: sampleHolderPivot
  });
  createPart('SampleTrayBase', boxGeo(0.44, 0.02, 0.54), m.panelGray, {
    position: [0, 0.01, 0],
    parent: sampleHolderPivot
  });

  // 3 circular cylindrical sample tube wells (along Z)
  const wellRadius = 0.080;
  const wellSpacing = 0.16;
  for (let w = -1; w <= 1; w++) {
    const wellZ = w * wellSpacing;
    // Outer collar ring
    createPart(`WellCollar_${w + 1}`, cylinderGeo(wellRadius + 0.015, wellRadius + 0.02, 0.035, 12), m.panelGray, {
      position: [0, 0.025, wellZ],
      parent: sampleHolderPivot
    });
    // Inner dark tube socket
    createPart(`WellSocket_${w + 1}`, cylinderGeo(wellRadius, wellRadius, 0.045, 12), m.trim, {
      position: [0, 0.022, wellZ],
      parent: sampleHolderPivot
    });
  }

  // B. Center insert: Test kit / Analysis recessed pad (Center Z = 0)
  const testKitPivot = createPivot('test_kit_slot', [0, 0.82, 0.0], root);

  // Pad rim
  createPart('TestPadRim', boxGeo(0.44, 0.025, 0.64), m.panel, {
    position: [0, 0.012, 0],
    parent: testKitPivot
  });
  // Dark inspection recessed mat / screen
  createPart('TestPadMat', boxGeo(0.38, 0.018, 0.56), m.trim, {
    position: [0, 0.016, 0],
    parent: testKitPivot
  });
  // Front grip notch / alignment tab
  createPart('TestPadTab', boxGeo(0.06, 0.020, 0.16), m.panelGray, {
    position: [0.19, 0.018, 0],
    parent: testKitPivot
  });

  // C. Right equipment: Desktop Science Analyser Unit (-Z side)
  const analyzerPivot = createPivot('analyzer', [0, 0.82, -0.66], root);

  // Support base collar
  createPart('AnalyzerBaseCollar', boxGeo(0.46, 0.05, 0.42), m.panelGray, {
    position: [0, 0.025, 0],
    parent: analyzerPivot
  });

  // Main ivory housing block
  const aH = 0.20;
  const aW = 0.40;
  const aL = 0.36;
  createPart('AnalyzerHousing', boxGeo(aW, aH, aL), m.panel, {
    position: [-0.02, 0.05 + aH / 2, 0],
    parent: analyzerPivot
  });

  // Orange chamfered side cheeks (on +Z and -Z faces)
  createPart('AnalyzerCheek_L', boxGeo(aW * 0.75, aH * 0.70, 0.035), m.accent, {
    position: [-0.02, 0.05 + aH / 2, aL / 2 + 0.015],
    parent: analyzerPivot
  });
  createPart('AnalyzerCheek_R', boxGeo(aW * 0.75, aH * 0.70, 0.035), m.accent, {
    position: [-0.02, 0.05 + aH / 2, -aL / 2 - 0.015],
    parent: analyzerPivot
  });

  // Angled console front sloping backward towards -X
  const consoleX = aW / 2 - 0.04;
  const consoleY = 0.05 + aH * 0.50;
  createPart('AnalyzerFacePlate', boxGeo(0.06, 0.16, aL * 0.84), m.panel, {
    position: [consoleX, consoleY, 0],
    rotation: [0, 0, 25],
    parent: analyzerPivot
  });

  // Glowing Cyan Screen (semantic 'screen' node)
  const screenPivot = createPivot('screen', [consoleX + 0.018, consoleY + 0.022, 0], analyzerPivot);
  screenPivot.rotation.z = 25 * Math.PI / 180;
  createPart('ScreenMesh', boxGeo(0.015, 0.08, 0.18), m.glowCool, {
    position: [0, 0, 0],
    parent: screenPivot
  });

  // 3 Console push buttons below screen
  for (let b = -1; b <= 1; b++) {
    const btnZ = b * 0.06;
    createPart(`ConsoleButton_${b + 1}`, boxGeo(0.02, 0.025, 0.04), m.panelGray, {
      position: [consoleX + 0.022, consoleY - 0.045, btnZ],
      rotation: [0, 0, 25],
      parent: analyzerPivot
    });
  }

  // Top Sensor Beacon: dark collar + glowing cyan sensor gem
  const topBeaconY = 0.05 + aH + 0.015;
  createPart('BeaconCollar', cylinderGeo(0.055, 0.065, 0.03, 8), m.trim, {
    position: [-0.02, topBeaconY, 0],
    parent: analyzerPivot
  });
  createPart('BeaconCyanGem', boxGeo(0.065, 0.075, 0.065), m.glowCool, {
    position: [-0.02, topBeaconY + 0.045, 0],
    parent: analyzerPivot
  });

  // Define Category Budget
  defineBudget({ triangles: BUDGETS['medium-prop'] }, root);

  return root;
}
